import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in the rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts valid boundary rates", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.20 },
      0.05,
    );

    it("uses the matching region rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("rounds down (floors) the tax", () => {
      // 20% of 101 = 20.2 → 20
      expect(calc.computeTaxCents(101, "FR")).toBe(20);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("handles default rate of 0 for missing region", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.05 });
      expect(noDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using the provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10% of 1000 = 100
    expect(await calc.computeTaxCents(1000, "US")).toBe(100);
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable amount", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable amount", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("throws RangeError for invalid rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("service unavailable");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service unavailable",
    );
  });
});

describe("totalLineWeightGrams", () => {
  const mkProduct = (id: string, weightGrams?: number): Product => ({
    id,
    name: id,
    unitPriceCents: 100,
    weightGrams,
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: mkProduct("a", 500), quantity: 2 },
      { product: mkProduct("b", 300), quantity: 3 },
    ];
    // 500*2 + 300*3 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats undefined weight as 0", () => {
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
