import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

function mkProduct(id: string, weightGrams?: number): Product {
  return { id, name: id, unitPriceCents: 1000, weightGrams };
}

function mkLines(items: Array<{ id: string; qty: number; weight?: number }>): CartLine[] {
  return items.map((i) => ({
    product: mkProduct(i.id, i.weight),
    quantity: i.qty,
  }));
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    const lines = mkLines([{ id: "a", qty: 3 }]);
    expect(calc.computeShippingCents(lines, 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      const lines = mkLines([{ id: "a", qty: 1 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      const lines = mkLines([{ id: "a", qty: 1 }]);
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      const lines = mkLines([{ id: "a", qty: 1 }]);
      expect(calc.computeShippingCents(lines, 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      const lines = mkLines([{ id: "a", qty: 1 }]);
      expect(calc.computeShippingCents(lines, 4999)).toBe(599);
    });

    it("charges shipping without freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500);
      const lines = mkLines([{ id: "a", qty: 1 }]);
      expect(calc.computeShippingCents(lines, 100_000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for cart where all products have no weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = mkLines([{ id: "a", qty: 2 }]); // no weight
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the first bracket that fits the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 250g * 1 = 250g → first bracket (up to 500g) = 300
      const lines = mkLines([{ id: "a", qty: 1, weight: 250 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects exact boundary bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → first bracket = 300
      const lines = mkLines([{ id: "a", qty: 1, weight: 500 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket = 600
      const lines = mkLines([{ id: "a", qty: 1, weight: 501 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g exceeds all brackets, overflow defaults to last bracket cost = 1200
      const lines = mkLines([{ id: "a", qty: 1, weight: 6000 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses explicit overflowCostCents when provided", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = mkLines([{ id: "a", qty: 1, weight: 6000 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("sorts brackets regardless of input order", () => {
      // Provide brackets out of order
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      // 250g → should match first sorted bracket (500g) = 300
      const lines = mkLines([{ id: "a", qty: 1, weight: 250 }]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g * 2 + 100g * 3 = 900g → second bracket = 600
      const lines = mkLines([
        { id: "a", qty: 2, weight: 300 },
        { id: "b", qty: 3, weight: 100 },
      ]);
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });
  });
});

