toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function mkProduct(id: string, price = 100): Product {
  return { id, name: id, unitPriceCents: price };
}

describe("InventoryError", () => {
  it("has the correct name and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(200)
        .mockResolvedValueOnce(350),
    };
    const lines: CartLine[] = [
      { product: mkProduct("a", 100), quantity: 2 },
      { product: mkProduct("b", 150), quantity: 1 },
    ];

    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(200);
    expect(refreshed[0]!.quantity).toBe(2);
    expect(refreshed[1]!.product.unitPriceCents).toBe(350);
    expect(refreshed[1]!.quantity).toBe(1);
  });

  it("does not mutate the original lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const original: CartLine[] = [
      { product: mkProduct("a", 100), quantity: 1 },
    ];

    await refreshPrices(original, fetcher);

    expect(original[0]!.product.unitPriceCents).toBe(100);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 1 },
    ];

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 1 },
    ];

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 1 },
    ];

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network error");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };

    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

