import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function mkProduct(id: string, price = 1000, weight?: number): Product {
  return { id, name: `Product ${id}`, unitPriceCents: price, weightGrams: weight };
}

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(mkProduct("a"), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(mkProduct("a"), 2);
    cart.add(mkProduct("a"), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("throws on non-positive quantity for add", () => {
    expect(() => cart.add(mkProduct("a"), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a"), -1)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a"), 1.5)).toThrow(RangeError);
  });

  it("throws on negative unit price", () => {
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(mkProduct("a"), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    cart.add(mkProduct("a"), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes product when updateQuantity is called with 0", () => {
    cart.add(mkProduct("a"), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws on updateQuantity for unknown product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("throws on negative updateQuantity", () => {
    cart.add(mkProduct("a"), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws on non-integer updateQuantity", () => {
    cart.add(mkProduct("a"), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clears all products", () => {
    cart.add(mkProduct("a"), 1);
    cart.add(mkProduct("b"), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns a deep copy — mutations do not affect internal state", () => {
    cart.add(mkProduct("a", 500), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    snap[0]!.product.unitPriceCents = 1;
    expect(cart.snapshot()[0]!.quantity).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);
    cart.add(mkProduct("b", 300), 3);
    const totals = cart.totals();
    // 500*2 + 300*3 = 1900
    expect(totals.subtotalCents).toBe(1900);
  });

  it("returns all zeros for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy via the pipeline", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(mkProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(200);
    expect(totals.totalCents).toBe(800); // 1000 - 200
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 5000,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(mkProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(mkProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("tax is computed on the discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(mkProduct("a", 1000), 1);

    cart.totals();
    // Tax should be called with discounted subtotal (1000 - 200 = 800)
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(mkProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.shippingCents).toBe(500);
    // shipping receives (lines, discountedSubtotal)
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900, // 1000 - 100
    );
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 200 },
      taxCalculator: { computeTaxCents: () => 80 },
      shippingCalculator: { computeShippingCents: () => 500 },
    });
    cart.add(mkProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    expect(totals.taxCents).toBe(80);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("negative tax is clamped to 0", () => {
    const cart = new Cart({
      taxCalculator: { computeTaxCents: () => -50 },
    });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping is clamped to 0", () => {
    const cart = new Cart({
      shippingCalculator: { computeShippingCents: () => -100 },
    });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default region US", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(mkProduct("a", 100), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(100, "US");
  });
});

describe("Cart — async checkout()", () => {
  it("returns totals and lines for basic checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);

    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };

    const result = await cart.checkout({ priceFetcher });
    // Refreshed price: 600 * 2 = 1200
    expect(result.totals.subtotalCents).toBe(1200);
    expect(result.lines[0]!.product.unitPriceCents).toBe(600);
  });

  it("throws InventoryError when inventory check denies", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available=true but qty insufficient)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes when inventory check approves", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("uses asyncTaxProvider for tax calculation during checkout", async () => {
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 100 },
      region: "US-CA",
    });
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=100, discountedSubtotal=900
    // async tax: 10% of 900 = 90
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.totalCents).toBe(900 + 90); // 990
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const cart = new Cart({
      shippingCalculator: { computeShippingCents: () => 500 },
      region: "FR",
    });
    cart.add(mkProduct("a", 100), 2);
    cart.add(mkProduct("b", 200), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(150) // product a → 150
        .mockResolvedValueOnce(250), // product b → 250
    };

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // Refreshed: 150*2 + 250*1 = 550
    expect(result.totals.subtotalCents).toBe(550);
    // No discount policy → discount = 0
    // Tax: 20% of 550 = 110
    expect(result.totals.taxCents).toBe(110);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(550 + 110 + 500); // 1160
  });

  it("propagates priceFetcher error", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("inventory denial generates default message when no reason provided", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.message).toContain("a");
      expect(invErr.available).toBe(0);
    }
  });

  it("checks inventory for each product — first denial wins", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 1);
    cart.add(mkProduct("b", 300), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});

